@push('scripts')
<script>
const slides=[...document.querySelectorAll('.question-slide')],navs=[...document.querySelectorAll('.q-nav')];let current=0;
function showQuestion(index){if(!slides.length)return;current=Math.max(0,Math.min(index,slides.length-1));slides.forEach((el,i)=>el.classList.toggle('active',i===current));navs.forEach((el,i)=>el.classList.toggle('active',i===current));window.scrollTo({top:0,behavior:'smooth'});}
function updateProgress(){const answered=new Set([...document.querySelectorAll(".answer-control")].filter(el=>el.type==="radio"?el.checked:el.value.trim()!=="").map(el=>el.dataset.question));document.getElementById("answeredCount").textContent=answered.size;document.getElementById("progressBar").style.width=(slides.length?answered.size/slides.length*100:0)+"%";navs.forEach(n=>n.classList.toggle("answered",answered.has(n.dataset.question)));}
document.querySelectorAll('.answer-control').forEach(el=>el.addEventListener(el.type==='radio'?'change':'input',updateProgress));navs.forEach(n=>n.addEventListener('click',()=>showQuestion(Number(n.dataset.go))));document.querySelectorAll('.prev-btn').forEach(b=>b.addEventListener('click',()=>showQuestion(current-1)));document.querySelectorAll('.next-btn').forEach(b=>b.addEventListener('click',()=>showQuestion(current+1>=slides.length?0:current+1)));document.getElementById('revealAnswers')?.addEventListener('change',e=>document.querySelectorAll('.option.correct').forEach(option=>option.classList.toggle('reveal',e.target.checked)));updateProgress();
</script>
@endpush